BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('linux-q95', 'systemdとサービス管理',
   'Webサーバーやデータベースのように、起動したあとも裏でずっと動き続け、リクエストが来るたびに処理する種類のプログラムを何と呼ぶか。',
   NULL::text,
   '["サービス（常駐して待ち構え続けるプログラム）", "スクリプト（決まった手順を書いた一回限りの実行手順）", "コマンド（呼ばれた瞬間だけ動いて終わるプログラム）", "ライブラリ（他のプログラムから部品として呼ばれるコード）"]',
   0, '[0]', 'single',
   '{"asked": "起動後も裏で待ち構え続けるプログラムの呼び名を選ぶ問題。", "point": "「動いて終わる」のではなく「動き続けて待つ」プログラムがサービス。", "kid": "`ls`のようなふつうのコマンドは、実行されたらすぐ答えを返して終わってしまう。でもWebサーバーは、リクエストがいつ来てもいいように、ずっと起動したまま待ち構え続ける。この「動き続けて、来た仕事をその都度こなす」タイプのプログラムをサービスと呼ぶ。", "eg": "たとえるなら、コマンドは「聞かれたら一言だけ答えてすぐ帰る店員」。サービスは「お店を開けっぱなしにして、お客が来るたびに接客し続ける店員」。", "terms": [["サービス", "起動したまま裏で待機し、要求のたびに処理する常駐プログラム"], ["デーモン", "サービスとほぼ同じ意味で使われる、バックグラウンドで動き続けるプロセスの呼び方"]], "think": "なぜこの区別が要るのかがカギ。もしWebサーバーが`ls`のように呼ばれるたび起動して終わっていたら、リクエストが来る前にもう終了していて、いつまでも応答できない。「動き続けて待つ」という性質があってはじめて、いつ来るか分からないリクエストに対応できる。", "vs": "スクリプトと混同しやすいが、スクリプトは「決まった手順を上から下まで実行して終わる」もので、実行し続けて待ち構える性質はない。", "opt": ["正解。起動したまま裏で待ち構え続け、来た仕事をその都度こなすプログラムをサービスと呼ぶ。", "スクリプトは決まった手順を実行して終わるもので、動き続けて待ち構える性質はサービスの特徴。", "コマンドは呼ばれた瞬間だけ動いて答えを返し終了するもので、待ち構え続ける性質とは逆。", "ライブラリは他のプログラムから部品として呼ばれるコードの集まりで、単体で待ち構えて動き続けるものではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コマンド vs サービス</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">コマンド</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">呼ばれたら実行</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">終わったら消える</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">サービス</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">起動したまま待機</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">来るたび処理</text></svg>"}'),

  ('linux-q96', 'systemdとサービス管理',
   'サービスは裏で動き続けるため、誰かが見ていないと落ちたことに気づけない。サービスの状態を見守り、落ちていれば検知したり自動で立て直したりする役回りの仕組みを何と呼ぶか。',
   NULL::text,
   '["スーパーバイザ（プロセスの生死を見守る監督役の仕組み）", "コンパイラ（プログラムを機械語に変換する仕組み）", "ブラウザ（Webページを表示する仕組み）", "エディタ（ファイルの中身を書き換える仕組み）"]',
   0, '[0]', 'single',
   '{"asked": "サービスの生死を見守り、落ちたら対応する役回りの名前を選ぶ問題。", "point": "見張り役がいて初めて「落ちたら気づける・立て直せる」が実現する。", "kid": "サービスは裏で動き続けるからこそ、誰も見ていないところで急に落ちてしまうことがある。人間が四六時中画面を見張っているわけにはいかないので、代わりにプロセスの生死を見守り続け、落ちたら気づいたり立て直したりする役目を持つ仕組みが用意されている。これがスーパーバイザ。", "eg": "たとえるなら、お店の防犯カメラのようなもの。店員（サービス）が倒れても、カメラ（スーパーバイザ）がそれに気づいて、誰かに知らせたり応急処置を促したりしてくれる。", "terms": [["スーパーバイザ", "プロセスの生死を見守り、異常時に検知・再起動などの対応を行う仕組み"], ["systemd", "Linuxで広く使われているスーパーバイザ兼、起動処理全体を管理する仕組み"]], "think": "なぜ見守る仕組みが必要かがカギ。サービスは長時間動き続けるほど、バグやメモリ不足などで予期せず落ちる可能性が積み重なる。落ちたことに誰も気づかなければ、利用者はサービスが使えないまま放置される。スーパーバイザが常に見張っていることで、落ちた瞬間に検知したり、自動で立て直したりできる。", "vs": "コンパイラと混同しないよう注意。コンパイラはプログラムを事前に変換する道具であり、動いているプロセスを見守る役割は持たない。", "opt": ["正解。プロセスの生死を見守り、異常時に検知・対応する役回りをスーパーバイザと呼ぶ。", "コンパイラはプログラムのソースコードを機械語に変換する道具で、動いているプロセスの見守りとは無関係。", "ブラウザはWebページを表示するためのプログラムで、サービスの生死を見守る役割は持たない。", "エディタはファイルの中身を書き換えるための道具で、プロセスの監視とは別の目的のプログラム。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">見守る仕組み</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">サービス</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">裏で動く</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">スーパーバイザ</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">生死を監視</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">異常時</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">検知・対応</text></svg>"}'),

  ('linux-q97', 'systemdとサービス管理',
   'OSの起動時には、ネットワークの準備、ディスクのマウント、各種サービスの起動など多くの作業が必要になる。これらを闇雲に一斉スタートさせるのではなく、決まった順番で立ち上げる仕組みが要る理由として最も適切なものはどれか。',
   NULL::text,
   '["ある作業が別の作業の完了を前提にしている（依存関係がある）ため", "順番を決めておくと、起動にかかる時間が理論上ゼロになるため", "OSの規則で、起動処理は必ず1つずつしか実行できないと決まっているため", "順番を決めなくても実害はないが、見た目を整えるためだけの慣習だから"]',
   0, '[0]', 'single',
   '{"asked": "起動時の作業に順番管理が必要な理由を問う問題。", "point": "順番が要るのは「後の作業が、前の作業の完了を前提にしている」から。", "kid": "たとえばネットワークがまだ準備できていないのに、ネットワーク経由でファイルを取りに行くサービスを先に起動してしまったら、失敗してしまう。「これが終わっていないと、あれは始められない」という前後関係（依存関係）があるので、起動処理には正しい順番が要る。", "eg": "たとえるなら、朝の支度で「顔を洗ってから化粧水をつける」のように、前の作業が終わっていないと次の作業が意味をなさない場面と同じ。全部を同時にやろうとすると、まだ濡れた顔に化粧水をつけるような失敗が起きる。", "terms": [["依存関係", "ある作業が、別の作業の完了を前提にしている関係"], ["起動処理（ブート処理）", "OSが立ち上がる際に必要な準備を順に済ませていく一連の作業"]], "think": "なぜ闇雲な一斉スタートがまずいのかがカギ。作業同士には「これが終わっていないと始められない」という依存関係が存在する。順番を無視して一斉に始めると、前提が整っていない作業が失敗したり、不安定な状態で動き出したりする。systemdのような仕組みは、この依存関係を管理して、正しい順番（もしくは依存のないものは並行して）起動できるようにしている。", "vs": "「必ず1つずつ順番に」という誤解に注意。依存関係のない作業同士は、むしろ同時に並行して起動されることも多く、順番管理の目的は「1つずつ」ではなく「前提が整ってから」始めること。", "opt": ["正解。ある作業が別の作業の完了を前提にしている依存関係があるため、正しい順番での起動が必要になる。", "順番を決めても起動時間がゼロになるわけではなく、あくまで正しい前提の上で作業を進めるための工夫。", "依存関係のない作業同士は並行して起動されることもあり、必ず1つずつという決まりではない。", "順番管理は見た目のためではなく、前提が整っていない作業の失敗を防ぐという実質的な理由がある。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">依存関係のある起動順</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ディスクをマウント</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ネットワーク準備</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">2</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">サービス起動</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">3</text></svg>"}'),

  ('linux-q98', 'systemdとサービス管理',
   'あるサービスがバグで突然落ちてしまった。systemdのようなスーパーバイザがこの状況で自動的に行おうとする、代表的な対応はどれか。',
   NULL::text,
   '["設定に従って、落ちたサービスをもう一度自動的に起動し直す", "落ちたサービスの設定ファイルを自動的に削除する", "OS全体を強制的に再起動する", "落ちたサービスが使っていたディスク領域をすべてフォーマットする"]',
   0, '[0]', 'single',
   '{"asked": "サービスが落ちたときのスーパーバイザの代表的な対応を問う問題。", "point": "落ちたら「もう一度起動し直す」がまず試される標準的な立て直し方。", "kid": "サービスが突然落ちても、そのまま放置されたら困る利用者がいる。そこでスーパーバイザは、設定で「落ちたら自動的に起動し直す」ように指示しておくことができる。人間が気づいて手で再起動するより早く、自動的に復旧を試みてくれる。", "eg": "たとえるなら、倒れた店員をそのままにせず、すぐに交代の店員をレジに立たせて営業を続けようとするお店の対応と同じ。", "terms": [["自動再起動", "落ちたサービスを、設定に基づいて自動的にもう一度起動する仕組み"]], "think": "なぜ自動再起動が代表的な対応なのかがカギ。サービスが落ちる原因は一時的な不具合であることも多く、もう一度起動し直すだけで正常に戻ることが少なくない。人間が気づいて対応するには時間がかかるが、スーパーバイザが即座に再起動を試みることで、利用できない時間（ダウンタイム）を短くできる。", "vs": "「落ちたら設定ごと消す」という誤解に注意。設定ファイルを消してしまうと、次に正しく起動する手段まで失われてしまい、むしろ復旧を妨げる。", "opt": ["正解。設定に従って落ちたサービスをもう一度自動的に起動し直すのが代表的な対応。", "設定ファイルを自動的に削除してしまうと、正しく起動するための手がかりまで失われ、復旧の妨げになる。", "1つのサービスが落ちただけでOS全体を強制再起動するのはやりすぎで、他の正常なサービスまで巻き添えにしてしまう。", "サービスが使っていたディスク領域を丸ごとフォーマットすると、保存していたデータまで消えてしまい復旧にならない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">落ちたサービスの自動復旧</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">サービス</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">動作中</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">突然落ちる</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">検知</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">自動再起動</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">復旧</text></svg>"}'),

  ('linux-q99', 'systemdとサービス管理',
   'OSが起動して最初に生まれる、特別な番号(PID 1)を持つプロセスには、他のすべてのプロセスの「大元の親」のような役割がある。この特別なプロセスの役割として最も適切なものはどれか。',
   NULL::text,
   '["以降に起動するすべてのプロセスの管理を担う起点になる", "ハードウェアの計算処理そのものを行う唯一のプロセスになる", "ネットワーク通信だけを専門に担当するプロセスになる", "ユーザーがキーボードを打つたびに毎回新しく生成し直される"]',
   0, '[0]', 'single',
   '{"asked": "OS起動時に最初に生まれる特別なプロセス(PID 1)の役割を問う問題。", "point": "PID 1は「以降のすべてのプロセスの大元」という特別な起点。", "kid": "OSが起動すると、まず最初に1つのプロセスが生まれる。これが特別な番号「PID 1」を持つプロセスで、systemdのようなスーパーバイザがこの役目を担うことが多い。以降に起動する他のすべてのプロセスは、直接・間接にこのプロセスから枝分かれして生まれてくる、いわば大元の親のような存在になる。", "eg": "たとえるなら、家系図の一番上にいる「ご先祖様」のようなもの。以降の子孫（他のプロセス）は、たどっていくと必ずこのご先祖様に行き着く。", "terms": [["PID", "プロセスにつけられる識別番号"], ["PID 1", "OS起動時に最初に生まれる、特別な役割を持つプロセスの番号"]], "think": "なぜPID 1が特別なのかがカギ。プロセスは親プロセスから生まれる（プロセスという考え方のカテゴリで学んだ親子関係）が、その連鎖を遡っていくと必ず最初の1つに行き着く。この最初のプロセスがいなければ、そもそも他のどのプロセスも生まれるきっかけを持てない。だからPID 1は「以降のすべてのプロセスの管理を担う起点」という特別な役割を持つ。", "vs": "「PID 1はハードウェアの計算処理を行う」という誤解に注意。計算処理自体はCPUやカーネルの仕事で、PID 1はあくまでプロセスの管理・起動の起点という役割。", "opt": ["正解。PID 1は以降に起動するすべてのプロセスの、直接・間接の大元となる管理の起点。", "計算処理そのものを行うのはCPUやカーネルの役目で、PID 1はプロセス管理の起点という別の役割。", "ネットワーク通信は専用のサービスが担当することが多く、PID 1の役割はもっと広い管理全般にある。", "PID 1はOS起動時に一度生まれてから動き続けるプロセスで、キー入力のたびに生成し直されるものではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">PID 1を起点とした親子関係</text><rect x=\"140\" y=\"32\" width=\"60\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"170\" y=\"49\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">PID 1</text><line x1=\"170\" y1=\"58\" x2=\"55.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"10.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"55.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">サービスA</text><line x1=\"170\" y1=\"58\" x2=\"170.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"125.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">サービスB</text><line x1=\"170\" y1=\"58\" x2=\"285.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"240.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"285.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">…</text></svg>"}'),

  ('linux-q100', 'systemdとサービス管理',
   'サービスの「今の状態」を確かめたいとき、動いているのか止まっているのかを判断する材料として最も的確なものはどれか。',
   NULL::text,
   '["そのサービスに対応するプロセスが、今も生きて動き続けているかどうか", "そのサービスの設定ファイルが、ディスク上に存在するかどうか", "そのサービスの名前が、辞書的に正しい英単語であるかどうか", "そのサービスを最初にインストールした日付が、何日前かどうか"]',
   0, '[0]', 'single',
   '{"asked": "サービスが動いているかどうかを判断する材料を問う問題。", "point": "「動いているか」を決めるのは、対応するプロセスが生きているかどうか。", "kid": "サービスが「動いている」とは、そのサービスに対応するプロセスが今もOS上で生きて存在し続けている、ということ。設定ファイルがディスクにあるだけでは、まだ起動していない可能性もあるし、逆にプロセスが落ちていても設定ファイル自体は残り続ける。「今その瞬間、プロセスが生きているか」が状態を判断する材料になる。", "eg": "たとえるなら、お店が「営業中」かどうかを知りたいとき、看板（設定ファイル）が出ているかではなく、実際に店員（プロセス）が中にいて働いているかを見るのと同じ。", "terms": [["プロセスの状態", "そのプロセスが今も動き続けているか、それとも終了しているかという情報"]], "think": "なぜ設定ファイルの有無では判断できないのかがカギ。設定ファイルは「起動するときの手順書」であって、動いているかどうかとは別の話。手順書がディスクに残っていても、実際にそれを使ってプロセスが起動され、今も生きているとは限らない。だからサービスの状態確認は、常に「今その瞬間のプロセスの生死」を見る作業になる。", "vs": "「インストール日」と混同しないよう注意。いつインストールしたかは過去の記録にすぎず、今この瞬間に動いているかどうかとは無関係。", "opt": ["正解。そのサービスに対応するプロセスが今も生きて動き続けているかどうかが、状態を判断する材料になる。", "設定ファイルがディスクにあるかどうかは起動の手順書があるかの確認であり、今動いているかとは別の話。", "サービス名が正しい英単語かどうかは動作状態と無関係で、判断材料にはならない。", "インストールした日付は過去の記録であり、今この瞬間動いているかどうかの判断材料にはならない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">設定ファイル vs 動作状態</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">設定ファイル</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">ディスク上の手順書</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">常に存在しうる</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">プロセスの状態</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">今生きているか</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">動作中/停止で変わる</text></svg>"}'),

  ('linux-q101', 'SSHとリモートアクセスの基礎',
   '離れた場所にあるサーバーに、インターネット越しでログインして操作したい。この通信を暗号化せずに素のまま送ってしまうと、最も懸念される問題はどれか。',
   NULL::text,
   '["通信経路の途中で、第三者にパスワードや操作内容を盗み見られてしまう", "サーバー側のディスク容量が自動的に減ってしまう", "サーバーのCPU使用率が常に100%に固定されてしまう", "ログインの度に、サーバーの時計がずれてしまう"]',
   0, '[0]', 'single',
   '{"asked": "リモートログインを暗号化しない場合の懸念点を問う問題。", "point": "暗号化しないと「経路の途中で盗み見られる」危険がある。", "kid": "遠く離れたサーバーへの通信は、途中でいろいろな中継地点を経由する。もし中身が暗号化されていない「素のまま」だと、その経路のどこかで盗み見ている第三者に、打ち込んだパスワードや操作の内容がそのまま読まれてしまう危険がある。", "eg": "たとえるなら、はがき（暗号化なし）で手紙を送ると、配達の途中の誰でも中身を読めてしまう。封筒に入れて鍵をかける（暗号化する）ことで、届け先以外には中身が読めないようにする。", "terms": [["暗号化", "通信の中身を、正しい鍵を持つ相手にしか読めない形に変換すること"], ["盗聴", "通信経路の途中で、第三者が中身をこっそり読み取ること"]], "think": "なぜ暗号化が要るのかがカギ。インターネットを経由する通信は、自宅から目的地まで一直線につながっているわけではなく、いくつもの中継地点を経由する。そのどこか1か所でも盗聴されると、素のままの通信内容（パスワードなど）がそのまま漏れてしまう。SSHは通信全体を暗号化することで、途中経路のどこで見られても中身が読めない状態を作っている。", "vs": "「サーバーの性能に影響する」という誤解に注意。暗号化の有無で懸念されるのは情報の漏洩であり、ディスク容量やCPU使用率が直接壊れるといった話ではない。", "opt": ["正解。暗号化されていない通信は、経路の途中で第三者にパスワードや操作内容を盗み見られてしまう危険がある。", "ディスク容量の減少は暗号化の有無とは無関係で、盗聴の懸念とは別の話。", "CPU使用率が固定されるという現象は暗号化の有無とは関係のない話。", "サーバーの時計のずれは別の仕組み（時刻同期）の話で、暗号化しているかどうかとは無関係。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">暗号化なし vs あり</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">暗号化なし</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">途中で盗み見られる</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">パスワードが漏れる</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">暗号化あり(SSH)</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">途中で読めない</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">鍵を持つ相手だけ復元</text></svg>"}'),

  ('linux-q102', 'SSHとリモートアクセスの基礎',
   '公開鍵認証には「秘密鍵」と「公開鍵」という2つの鍵が登場する。この2つの正しい扱い方はどれか。',
   NULL::text,
   '["秘密鍵は自分の手元だけに置き、公開鍵はログイン先のサーバーに登録して配ってよい", "秘密鍵をログイン先のサーバーに登録し、公開鍵は自分の手元だけに置く", "秘密鍵と公開鍵はどちらも自由に他人へ配ってよい共有情報である", "秘密鍵と公開鍵はどちらも他人には絶対に見せてはいけない情報である"]',
   0, '[0]', 'single',
   '{"asked": "秘密鍵と公開鍵、それぞれの正しい扱い方を問う問題。", "point": "「秘密」鍵は手元に、「公開」鍵は配ってよい。名前がそのままヒント。", "kid": "公開鍵認証では、対になった2つの鍵を使う。秘密鍵は名前の通り、自分だけが持っていて誰にも渡してはいけない鍵。公開鍵は逆に、誰に見られても構わない鍵で、ログインしたいサーバー側にあらかじめ登録しておく。この登録された公開鍵と、手元の秘密鍵が正しい対だと確認できたときだけログインが許可される。", "eg": "たとえるなら、秘密鍵は「自分だけが持つ実印」。公開鍵は「この人の印鑑と分かる、公開されている印影の見本」。見本（公開鍵）を配っても実印そのもの（秘密鍵）を渡したことにはならない。", "terms": [["秘密鍵", "自分だけが持ち、絶対に他人に渡さない鍵"], ["公開鍵", "サーバー側に登録し、誰に見られても構わない鍵"]], "think": "なぜこの分担が安全なのかがカギ。もし1本の鍵だけでログインを確認する仕組みだと、その鍵をサーバーに渡す必要があり、サーバー側が漏洩すれば鍵ごと盗まれてしまう。公開鍵と秘密鍵に分けることで、サーバー側には「見られても平気な公開鍵」しか渡さずに済み、本人確認に必要な秘密鍵は一度も外に出ないまま認証ができる。", "vs": "パスワード認証と混同しやすいが、パスワードはサーバー側にも（形を変えて）情報を渡す必要があるのに対し、公開鍵認証は秘密鍵そのものを一切サーバーに渡さない点が違う。", "opt": ["正解。秘密鍵は自分の手元だけに置き、公開鍵はログイン先のサーバーに登録して配ってよい。", "秘密鍵をサーバーに登録してしまうと、サーバー側が漏洩したときに秘密鍵ごと盗まれてしまい危険。", "秘密鍵は誰にも渡してはいけない鍵で、自由に配ってよいわけではない。", "公開鍵は名前の通り公開してよい鍵で、絶対に見せてはいけない情報ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">秘密鍵と公開鍵</text><rect x=\"30\" y=\"40\" width=\"120\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#c47070\"/><text x=\"90\" y=\"60\" font-size=\"11\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"bold\">秘密鍵</text><text x=\"90\" y=\"78\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">自分の手元だけ</text><rect x=\"190\" y=\"40\" width=\"120\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\"/><text x=\"250\" y=\"60\" font-size=\"11\" fill=\"#6ab08d\" text-anchor=\"middle\" font-weight=\"bold\">公開鍵</text><text x=\"250\" y=\"78\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">サーバーに登録</text><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><line x1=\"190\" y1=\"100\" x2=\"150\" y2=\"100\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><text x=\"170\" y=\"116\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">配っても安全</text></svg>"}'),

  ('linux-q103', 'SSHとリモートアクセスの基礎',
   'パスワード認証と公開鍵認証を比べたとき、公開鍵認証のほうが安全とされる理由として最も適切なものはどれか。',
   NULL::text,
   '["本人確認に使う秘密鍵そのものが、一度もサーバー側に渡らないから", "公開鍵認証だと、そもそも通信が暗号化されない仕組みだから", "公開鍵認証では、誰でもパスワード無しでログインできてしまうから", "公開鍵認証は、サーバー側の設定ファイルを一切必要としないから"]',
   0, '[0]', 'single',
   '{"asked": "公開鍵認証がパスワード認証より安全とされる理由を問う問題。", "point": "安全とされる核心は「本人確認の鍵そのものがサーバーに渡らない」こと。", "kid": "パスワード認証では、本人確認のための情報（パスワード）をサーバー側にも何らかの形で渡す必要がある。もしサーバーの情報が漏れたら、そのパスワードも一緒に危険にさらされる。公開鍵認証では、本人確認に使う秘密鍵は一度もサーバーに渡さず、手元に置いたまま確認だけを行える。だから「渡していないものは盗まれようがない」という理屈で安全性が高いとされる。", "eg": "たとえるなら、パスワード認証は「合言葉を店員にも教えて、照合してもらう」やり方。公開鍵認証は「実印そのものは渡さず、印影の見本(公開鍵)だけを店に預けて、印影が一致するかで本人確認する」やり方。実印(秘密鍵)は一度も店に渡っていない。", "terms": [["パスワード認証", "本人確認の情報をサーバー側にも渡して照合する認証方式"], ["公開鍵認証", "本人確認の核心(秘密鍵)を一度もサーバーに渡さずに済む認証方式"]], "think": "なぜ「渡さない」ことが安全性につながるのかがカギ。情報漏洩の多くは、どこかに保存されていた情報が盗まれることで起きる。パスワード認証は、照合のためにパスワード（に由来する情報）をサーバー側にも保存しておく必要があり、そこが漏洩のリスクになる。公開鍵認証は、確認に必要な「見られても平気な公開鍵」だけをサーバーに置き、本人確認の核心である秘密鍵は一度も外に出ないため、サーバー側が漏洩しても秘密鍵自体は無事、という構造になっている。", "vs": "「公開鍵認証は暗号化していない」という誤解に注意。SSHはどちらの認証方式を使っても通信自体は暗号化されており、暗号化の有無で安全性が決まっているわけではない。", "opt": ["正解。本人確認に使う秘密鍵そのものが一度もサーバー側に渡らないことが、安全とされる核心の理由。", "公開鍵認証を使っていても通信自体はSSHとして暗号化されており、暗号化されない仕組みという記述は誤り。", "公開鍵認証は「鍵が正しく対応しているか」を厳密に確認する仕組みで、誰でも無条件で入れる仕組みではない。", "公開鍵認証でもサーバー側には公開鍵を登録しておく設定が必要で、設定が一切不要というわけではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">公開鍵認証の安全性</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">秘密鍵</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">手元のみ</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">一度も送信せず</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">確認</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ログイン許可</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">本人確認</text></svg>"}'),

  ('linux-q104', 'SSHとリモートアクセスの基礎',
   '初めて接続するサーバーにSSHでログインしようとすると、「このホストは初めて接続します。本当に接続しますか」というような確認が表示されることがある。この確認が存在する目的として最も適切なものはどれか。',
   NULL::text,
   '["接続先が、本当に意図したサーバー本人であるかを確かめるため", "サーバー側のディスク容量に余裕があるかを確認するため", "利用者のタイピング速度が基準を満たしているかを確認するため", "サーバーのOSのバージョンが最新かどうかを確認するため"]',
   0, '[0]', 'single',
   '{"asked": "初回接続時の確認メッセージが存在する目的を問う問題。", "point": "確認の目的は「相手が、なりすましではなく本物か」を確かめること。", "kid": "SSHで接続するとき、通信経路のどこかで悪意のある誰かが「本物のサーバーになりすまして」割り込んでくる可能性がある。初回接続時の確認は、接続先が本当に意図したサーバーかどうかを、サーバーごとに決まった目印(鍵の指紋のようなもの)で確かめるためにある。一度確認して覚えておけば、次回以降は自動的に「知っている相手」として扱われる。", "eg": "たとえるなら、初めて会う取引先の担当者と名刺交換して顔と名前を覚えておくようなもの。次に会ったときは「前と同じ人だ」とすぐ分かるが、もし別人が同じ会社の名を語って現れたら違和感に気づける。", "terms": [["ホスト認証", "接続先のサーバーが、本当に意図した相手かどうかを確かめる仕組み"], ["なりすまし", "第三者が本物のサーバーのふりをして割り込んでくること"]], "think": "なぜ「相手の確認」が必要かがカギ。SSHは通信内容を暗号化して守るが、暗号化だけでは「そもそも通信している相手が本物かどうか」までは保証できない。もし偽物のサーバーに気づかず接続してしまうと、暗号化されたやり取りの中身をその偽物にそのまま渡すことになってしまう。初回確認の仕組みは、この「相手が本物かどうか」というもう1つの安全性を補っている。", "vs": "「暗号化の確認」だと誤解しやすいが、暗号化するかどうかとは別に、相手が本物かどうかを確かめるための仕組みという点が異なる。", "opt": ["正解。接続先が本当に意図したサーバー本人であるかを確かめることが、この確認の目的。", "ディスク容量の確認は接続先が本物かどうかとは無関係な話。", "タイピング速度の確認という仕組みはSSHには存在せず、接続先の確認とは無関係。", "OSのバージョン確認は接続先が本物かどうかを確かめる仕組みとは目的が異なる。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">初回接続の確認</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">接続要求</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">初めての相手</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">目印を確認</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">本物か判定</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">覚える</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">次回から自動</text></svg>"}'),

  ('linux-q105', 'SSHとリモートアクセスの基礎',
   'SSHで守っているのは主に「通信の中身」だが、では手元のパソコンに保存してある秘密鍵ファイル自体を守る責任は誰にあるか。',
   NULL::text,
   '["秘密鍵を保管している利用者自身", "接続先のサーバーの管理者", "SSHという通信の仕組みそのもの", "インターネットの回線を提供している通信会社"]',
   0, '[0]', 'single',
   '{"asked": "秘密鍵ファイルそのものを守る責任がどこにあるかを問う問題。", "point": "SSHが守るのは通信経路。鍵ファイルそのものの保管責任は持ち主にある。", "kid": "SSHという仕組みが暗号化して守ってくれるのは、あくまで「通信している最中の中身」。手元のパソコンに保存してある秘密鍵ファイルそのものが盗まれてしまったら、SSHの暗号化とは別の話として、その鍵を使ってなりすましログインされてしまう危険がある。だから秘密鍵ファイルを大切に保管する責任は、それを持っている利用者自身にある。", "eg": "たとえるなら、頑丈な金庫（SSHの暗号化）があっても、金庫の鍵そのものを机の上に置きっぱなしにしていたら意味がない。鍵の管理は金庫の仕組みではなく、鍵を持つ本人の責任。", "terms": [["秘密鍵ファイル", "利用者の手元のパソコンに保存されている、本人確認の核心となるファイル"], ["鍵の保管", "鍵ファイルを他人に見られたり盗まれたりしないように管理すること"]], "think": "なぜ責任が利用者側にあるのかがカギ。SSHが暗号化で守っているのは「通信経路の途中」であって、通信が始まる前の「鍵ファイルそのものの保管状態」までは面倒を見てくれない。もし秘密鍵ファイルがパソコンごと盗まれたり、うっかり他人に渡してしまったりすれば、その鍵を持つ人は誰でも本人になりすましてログインできてしまう。だから秘密鍵ファイルの管理は、通信の仕組みの外側にある、利用者自身の責任範囲になる。", "vs": "「サーバー管理者の責任」という誤解に注意。サーバー側が守れるのは登録された公開鍵の管理までで、利用者の手元にある秘密鍵ファイルの保管まではサーバー側の責任が及ばない。", "opt": ["正解。秘密鍵ファイルを保管している利用者自身に、その管理の責任がある。", "サーバーの管理者が守れるのは登録された公開鍵の管理までで、利用者の手元の秘密鍵までは責任が及ばない。", "SSHという仕組みが守るのは通信の中身であり、鍵ファイルそのものの保管まで面倒を見る仕組みではない。", "通信会社は回線を提供しているだけで、利用者の手元にあるファイルの保管責任までは負わない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">SSHが守る範囲</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">SSHが守る</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">通信中の中身</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">経路上の盗聴</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">利用者が守る</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">秘密鍵ファイル自体</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">手元での保管</text></svg>"}'),

  ('linux-q106', 'SSHとリモートアクセスの基礎',
   'テスト自動化のスクリプトから、CI環境で使うリモートサーバーに毎回パスワードを手入力せずに接続したい。この用途に最も向いている理由は、公開鍵認証のどのような性質によるものか。',
   NULL::text,
   '["秘密鍵ファイルさえ用意しておけば、パスワードの入力なしに自動で本人確認できる性質", "公開鍵認証を使うと、通信そのものが不要になる性質", "公開鍵認証を使うと、サーバー側の権限確認が一切不要になる性質", "公開鍵認証は人間がキーボードで入力したときしか機能しない性質"]',
   0, '[0]', 'single',
   '{"asked": "CI環境での自動接続に公開鍵認証が向いている理由を問う問題。", "point": "自動化に向くのは「その場でパスワードを打たせる必要がない」から。", "kid": "パスワード認証だと、接続のたびに人間がキーボードでパスワードを打つ場面が想定されている。しかしCIのような自動テストのスクリプトには、誰かがその場に張り付いてパスワードを打つことができない。公開鍵認証なら、あらかじめ用意しておいた秘密鍵ファイルを使うだけで本人確認が完了するので、人手を介さずに自動で接続できる。", "eg": "たとえるなら、パスワード認証は「毎回受付で名乗って合言葉を口で言う」やり方。公開鍵認証は「あらかじめ発行されたICカードをかざすだけで通過できる」やり方。ICカード（秘密鍵ファイル）を機械にセットしておけば、人が毎回声を出さなくても通過できる。", "terms": [["CI環境", "コードの変更のたびに自動でテストなどを実行する仕組み"], ["自動接続", "人間の手入力を介さずに、プログラムが自動的にログインを済ませること"]], "think": "なぜ「人手を介さない」ことが自動化に向くのかがカギ。CIのスクリプトは人間の介在なしに動くことが前提で、実行のたびにパスワードを求められると、そこで処理が止まってしまう。公開鍵認証は、秘密鍵ファイルという「あらかじめ用意しておける材料」だけで本人確認が完結するため、スクリプトの途中で誰かの入力を待つ必要がなく、自動化の流れを止めずに済む。", "vs": "「通信が不要になる」という誤解に注意。公開鍵認証を使っても、SSHによる通信自体は変わらず必要で、変わるのは本人確認の方法だけ。", "opt": ["正解。秘密鍵ファイルさえ用意しておけば、パスワード入力なしに自動で本人確認できる性質が自動化に向く。", "公開鍵認証を使っても、サーバーとの通信そのものは引き続き必要で、通信が不要になるわけではない。", "公開鍵認証を使っても、ログインした後の権限確認（何ができるか）は別途行われ、権限確認自体が不要になるわけではない。", "公開鍵認証はスクリプトなど人間の手入力なしの場面でも機能するからこそ自動化に向いており、人間の入力時だけ機能するわけではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">CIからの自動接続</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">CIスクリプト</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">人手なし</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">秘密鍵を使用</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">自動で本人確認</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ログイン成功</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">処理続行</text></svg>"}'),

  ('linux-q107', '定期実行とcronの仕組み',
   '毎晩深夜にログを整理するバックアップ処理を、人が毎回手で起動するのではなく自動化したい。このような「決まった時間に自動で動かす」仕組みが必要とされる、最も基本的な理由はどれか。',
   NULL::text,
   '["人が毎回起動する手間や、うっかり忘れるミスを防げるから", "決まった時間に実行すると、処理の内容が自動的に正しくなるから", "自動化すると、そのプログラムのバグが自動的に直るから", "決まった時間に実行しないと、OSが起動できなくなるから"]',
   0, '[0]', 'single',
   '{"asked": "定期実行の自動化が求められる基本的な理由を問う問題。", "point": "自動化の一番の狙いは「人手と、うっかり忘れを無くす」こと。", "kid": "深夜のバックアップのような処理を、人が毎晩起きて手で実行するのは現実的ではないし、寝坊したり忘れたりするミスも起きやすい。あらかじめ「毎日この時刻に、これを実行して」と設定しておけば、人が何もしなくても決まった時間に確実に動いてくれる。", "eg": "たとえるなら、毎朝同じ時刻に起きたい人が、目覚まし時計をセットしておくのと同じ発想。人が寝ずに時計を見張っていなくても、時計自身が時刻を見張っていて、指定した時刻になったら知らせてくれる。", "terms": [["定期実行", "決まった時刻・間隔で、自動的に処理を実行すること"], ["cron", "Linuxで定期実行を管理する代表的な仕組み"]], "think": "なぜ人の手を離れることが重要かがカギ。人が毎回覚えていて手動で実行する運用は、実行忘れ・実行時刻のばらつき・深夜対応の負担といった問題を抱える。決まった時刻に自動で起動する仕組みがあれば、これらの問題を丸ごと解消でき、処理の実行そのものを「思い出す」対象から外せる。", "vs": "「内容が自動的に正しくなる」という誤解に注意。定期実行が保証するのは「決まった時刻に確実に動く」ことであり、処理そのものの正しさ(バグの有無)を保証するものではない。", "opt": ["正解。人が毎回起動する手間や、うっかり忘れるミスを防げることが、定期実行の基本的な理由。", "定期実行はあくまで「決まった時刻に動かす」仕組みで、処理の内容そのものの正しさを保証するものではない。", "定期実行の仕組みがバグを自動的に直すことはなく、プログラムの中身は変わらない。", "定期実行しなくてもOS自体は問題なく起動でき、OSの起動と定期実行は別の話。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">手動実行 vs 定期実行</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">人が毎晩起動</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">忘れる可能性</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">cronに設定</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1回だけ</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">毎晩自動実行</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">忘れない</text></svg>"}'),

  ('linux-q108', '定期実行とcronの仕組み',
   'cronは「指定した時刻になったら処理を起動する」仕組みだが、この仕組みの正体として最も適切な説明はどれか。',
   NULL::text,
   '["時計を見張り続け、指定時刻になったら該当の処理を起動するプロセス", "指定した時刻になった瞬間だけ、OSの外側から突然出現するプログラム", "ユーザーがキーボードに触れている間だけ動き続ける対話的なプログラム", "一度だけ実行されたら、二度と存在しなくなる使い捨てのファイル"]',
   0, '[0]', 'single',
   '{"asked": "cronという仕組みの正体を問う問題。", "point": "cronの正体は「時計を見張り続けているプロセス」。", "kid": "cronは魔法のように時刻が来たら勝手に処理が始まるわけではなく、実は裏でずっと動き続けているプロセス（cronデーモン）が、時計を見張り続けている。設定された時刻になったら、そのプロセスが該当する処理を起動する、という仕組みになっている。", "eg": "たとえるなら、目覚まし時計そのものが「動き続けて時刻を見張っている」からこそ、決まった時刻にアラームが鳴る。時計が止まっていたら、いくら時刻を設定してもアラームは鳴らない。", "terms": [["cronデーモン", "時計を見張り続け、指定時刻になったら処理を起動するバックグラウンドのプロセス"], ["デーモン", "裏で動き続けるプロセスの呼び方（systemdとサービス管理のカテゴリで学んだサービスと同じ性質）"]], "think": "なぜ「見張り続けるプロセス」だと理解することが大事かがカギ。もしcronが単なる設定ファイルの中身に過ぎず、それを実行するプロセスが動いていなければ、指定した時刻になっても誰も気づいてくれず処理は起動しない。cronが定期実行を実現できているのは、裏で動き続けるプロセスが常に時計を確認し続けているから。この前提を理解すると、「サーバーが止まっている間はcronも動かない」という次の理解にもつながる。", "vs": "「時刻が来たら外から突然現れる」という誤解に注意。cronの処理は、あらかじめ動き続けているプロセスが起動するものであり、時刻をきっかけに新しく無から生まれるわけではない。", "opt": ["正解。時計を見張り続け、指定時刻になったら該当の処理を起動するプロセスがcronの正体。", "cronは常に動き続けているプロセスによって実現されており、時刻が来た瞬間に突然出現するものではない。", "cronはユーザーがキーボードに触れていなくても裏で動き続ける仕組みで、対話的な操作とは無関係。", "cronデーモン自体は使い捨てではなく、動き続けて何度も指定時刻ごとに処理を起動する。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">cronの正体</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">cronデーモン</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">常時稼働</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">時計を確認</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">指定時刻か</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">処理を起動</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">その時刻に</text></svg>"}'),

  ('linux-q109', '定期実行とcronの仕組み',
   'cronによって起動される定期実行のプロセスの「親」にあたるのは何か。',
   NULL::text,
   '["時計を見張り続けているcronデーモン自身", "その処理を最初に設定した人間のログインシェル", "たまたまその時刻に動いていた別の一般ユーザーのコマンド", "親プロセスは存在せず、独立して生まれる"]',
   0, '[0]', 'single',
   '{"asked": "cronで起動された処理の親プロセスが何かを問う問題。", "point": "cronが起動した処理の親は、見張り続けているcronデーモンそのもの。", "kid": "プロセスという考え方のカテゴリで学んだように、プロセスは基本的に他のプロセスから生まれる（親子関係）。cronによって起動される処理も例外ではなく、時計を見張り続けているcronデーモンが「親」となって、指定時刻にその処理（子プロセス）を起動する。", "eg": "たとえるなら、目覚まし時計（cronデーモン）が鳴った瞬間に、時計自身が「起きて朝食を作る係」を新しく呼び出すようなもの。呼び出された係（定期実行される処理）の生みの親は、時計そのもの。", "terms": [["親プロセス", "他のプロセスを生み出したプロセス"], ["cronデーモン", "指定時刻に処理を起動する、常時稼働のプロセス"]], "think": "なぜ親子関係を意識すると理解が進むのかがカギ。プロセスという考え方のカテゴリで学んだ「プロセスは親から生まれる」という原則は、cronの世界でもそのまま成り立つ。cronデーモンという常時稼働のプロセスが、指定時刻ごとに新しい子プロセスとして処理を起動している、と理解すれば、「サーバー(=cronデーモンを含むすべてのプロセス)が止まっていれば、そもそも子プロセスも生まれようがない」という次の理解にも自然につながる。", "vs": "「親プロセスは存在しない」という誤解に注意。Linuxのプロセスは、init(PID 1)を除いて必ず何らかの親プロセスから生まれる仕組みになっており、cronの子プロセスも例外ではない。", "opt": ["正解。時計を見張り続けているcronデーモン自身が、定期実行される処理の親プロセスになる。", "設定した人間のログインシェルは設定を書き込んだだけで、実際に処理を起動するのはcronデーモンの役目。", "たまたま動いていた別のユーザーのコマンドは、定期実行の処理とは無関係な独立したプロセス。", "Linuxのプロセスは基本的に何らかの親プロセスから生まれる仕組みで、親が存在しないという記述は誤り。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">cronデーモンを親とする起動</text><rect x=\"140\" y=\"32\" width=\"60\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"170\" y=\"49\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">cronデーモン</text><line x1=\"170\" y1=\"58\" x2=\"55.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"10.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"55.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">バックアップ処理</text><line x1=\"170\" y1=\"58\" x2=\"285.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"240.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"285.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ログ整理処理</text></svg>"}'),

  ('linux-q110', '定期実行とcronの仕組み',
   'サーバーが夜間メンテナンスでシャットダウンしていた間は、その時間帯に予定されていたcronの定期実行はどうなるか。',
   NULL::text,
   '["cronデーモン自体も止まっているため、その時間帯の実行は行われない", "サーバーが止まっていても、cronの処理だけは別の場所で必ず実行される", "サーバーが止まっていた分、次に起動した瞬間に必ず自動的に埋め合わせが行われる", "定期実行はサーバーの稼働状況に関係なく、時刻さえ来れば必ず実行される"]',
   0, '[0]', 'single',
   '{"asked": "サーバー停止中に予定されていた定期実行がどうなるかを問う問題。", "point": "cronもプロセスの一種なので、サーバーが止まればcronも止まっている。", "kid": "cronの正体は「時計を見張り続けているプロセス」だと学んだが、サーバーがシャットダウンしている間は、そのプロセス自体も動いていない。時計を見張る人がいなければ、指定時刻になったことに誰も気づけないので、その時間帯に予定されていた定期実行は行われないまま過ぎてしまう。", "eg": "たとえるなら、目覚まし時計の電源が切れている間は、いくら「7時に鳴る」設定をしていても鳴らないのと同じ。時計自体が動いていなければ、時刻を見張ることすらできない。", "terms": [["cronデーモン", "サーバーが稼働している間だけ動き続けている、時計を見張るプロセス"], ["ダウンタイム", "サーバーが停止していて動作していない時間帯"]], "think": "なぜサーバー停止中は実行されないのかがカギ。cronの定期実行を成り立たせているのは、常時稼働しているcronデーモンというプロセス。サーバー自体がシャットダウンしていれば、OS上のすべてのプロセスと同じくcronデーモンも動いていないので、時刻を見張ることも、処理を起動することもできない。「cronは特別な力で稼働状況に関係なく動く」わけではなく、あくまでサーバー上で動く1つのプロセスに過ぎない、という理解がここでの核心。", "vs": "「必ず埋め合わせが行われる」という誤解に注意。埋め合わせのような仕組みは特別に用意していない限り自動では行われず、標準的なcronの仕組みだけでは、その時間帯の実行は単に行われずに過ぎてしまう。", "opt": ["正解。cronデーモン自体もサーバー上の1つのプロセスなので、サーバーが止まっていればその時間帯の実行は行われない。", "cronの処理はサーバー上のcronデーモンによって行われるもので、サーバーの外の別の場所で勝手に実行されることはない。", "標準的なcronの仕組みだけでは、逃した実行を自動で埋め合わせる機能は用意されていない。", "定期実行はcronデーモンというプロセスに支えられており、サーバーの稼働状況と無関係に動くわけではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">サーバー稼働中 vs 停止中</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">稼働中</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">cronデーモンが動作</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">時刻通り実行</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">停止中</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">cronデーモンも停止</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">その時間帯は実行されない</text></svg>"}'),

  ('linux-q111', '定期実行とcronの仕組み',
   '定期実行しているバックアップ処理が、実は毎回失敗し続けていたことに1週間気づかなかった。この状況を早期に発見するために、定期実行の仕組みと組み合わせておくとよいものはどれか。',
   NULL::text,
   '["処理の実行結果を記録し、あとから確認できるようにしておくログの仕組み", "処理を定期実行ではなく、二度と実行されない一回限りの実行に変える", "処理の中身を、常に成功したことにする記述に書き換える", "処理が失敗しても、設定ファイルを自動的に削除する"]',
   0, '[0]', 'single',
   '{"asked": "定期実行の失敗に早く気づくための組み合わせを問う問題。", "point": "「動いたかどうか」を知りたいなら、結果を記録に残す仕組みと組み合わせる。", "kid": "cronは指定時刻に処理を起動してくれるが、その処理が成功したか失敗したかまでは、誰かが見ていない限り分からない。実行結果（成功したか、エラーが出たか）をログとして記録しておけば、あとから見返して「いつから失敗していたか」に気づける。ログとトラブルシューティングのカテゴリで学んだ「なぜログを見るか」がここでも生きてくる。", "eg": "たとえるなら、毎晩の見回り(定期実行)を記録ノート(ログ)に書き残しておけば、何日か経ってから見返して「この日から見回りが記録されていない」と異常に気づける。記録が無ければ、異常が起きていたことにすら気づけない。", "terms": [["ログ", "処理の実行結果や出来事を記録として残す仕組み"], ["定期実行の監視", "定期実行された処理が正しく完了したかを、あとから確認できるようにしておく工夫"]], "think": "なぜログとの組み合わせが要るのかがカギ。cronは「決まった時刻に起動する」ことは保証してくれるが、「起動した処理が成功したか」までは保証してくれない。処理が失敗して終わっても、画面に何も表示されない環境では、誰も気づかないまま失敗が積み重なってしまう。実行結果をログに残しておけば、QA実務で失敗したテストの原因を調査するのと同じように、あとから「いつ・何が」失敗したかを追跡できる。", "vs": "「一回限りの実行に変える」という誤解に注意。一回限りの実行に変えても、定期的な処理という目的自体が果たせなくなり、失敗に気づく手段にはならない。", "opt": ["正解。処理の実行結果を記録し、あとから確認できるようにしておくログの仕組みと組み合わせるとよい。", "一回限りの実行に変えると、定期的にバックアップを取るという本来の目的自体が果たせなくなる。", "処理の中身を常に成功したことにする記述に書き換えると、実際には失敗していても気づけなくなり逆効果。", "失敗のたびに設定ファイルを自動削除すると、次回以降そもそも実行自体が行われなくなってしまう。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">失敗への気づき方</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">cronで実行</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">毎晩</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">結果をログに記録</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">成功/失敗</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">あとから確認</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">早期発見</text></svg>"}'),

  ('linux-q112', '定期実行とcronの仕組み',
   '「毎日決まった時刻に繰り返し実行する」cronに対し、「今日の23時に一度だけ実行する」というような、繰り返さない単発の予約実行をしたい場合の考え方として最も適切なものはどれか。',
   NULL::text,
   '["繰り返し用の仕組みとは別に、一回限りの予約実行という別の考え方が存在する", "繰り返し実行の仕組みを、1回だけ実行してすぐ設定ごと削除すれば同じ効果になる", "定期実行の仕組みは繰り返し専用であり、単発の予約実行という概念自体が存在しない", "単発の予約実行をしたい場合は、必ず人間がその時刻までパソコンの前で待つ必要がある"]',
   0, '[0]', 'single',
   '{"asked": "繰り返さない単発の予約実行という考え方があるかを問う問題。", "point": "「繰り返す」と「一度だけ」は別の需要で、それぞれ別の仕組みとして考えられている。", "kid": "cronは「毎日」「毎週」のように繰り返す定期実行に向いている仕組み。しかし「今日の23時に一度だけ」のような、繰り返さない単発の予約には、また別の考え方の仕組みが用意されている。繰り返すか、一度きりかという違いによって、使う道具を使い分ける発想がある。", "eg": "たとえるなら、「毎朝7時に鳴る目覚まし時計」と「今夜だけ23時に鳴らしたいタイマー」は、同じ「決まった時刻に知らせる」役割でも、繰り返すか一度きりかで別の道具として使い分けられているのと同じ。", "terms": [["定期実行", "繰り返し、決まった間隔で処理を実行すること"], ["単発の予約実行", "一度だけ、指定した時刻に処理を実行すること"]], "think": "なぜ繰り返しと単発を分けて考えるのかがカギ。定期実行の仕組みは「毎回同じ間隔で繰り返す」ことに最適化されているため、単発の予約に無理に使うと、繰り返さないための後始末(設定を毎回消す作業)が余計に必要になる。最初から「一度だけ」という需要に向けて別の考え方の仕組みを用意しておいたほうが、目的に沿ったシンプルな使い方ができる。", "vs": "「同じ仕組みで代用できる」という誤解に注意。繰り返し用の仕組みを1回で削除して使い回すことは、目的が違う道具を無理に流用しているだけで、単発予約という別の考え方が存在すること自体は変わらない。", "opt": ["正解。繰り返し用の仕組みとは別に、一回限りの予約実行という別の考え方が存在する。", "繰り返し用の仕組みを1回だけ実行して削除するのは目的の異なる道具を無理に流用しているだけで、最初から別の考え方が用意されている。", "単発の予約実行という概念自体は存在し、繰り返し専用と言い切るのは誤り。", "単発の予約実行も裏で動くプロセスが時刻を見張る仕組みで実現でき、人間がその時刻まで張り付いている必要はない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">繰り返し vs 単発</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">定期実行(cron)</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">毎日/毎週など</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">繰り返し向け</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">単発の予約実行</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">一度だけ</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">繰り返さない需要向け</text></svg>"}'),

  ('linux-q113', '圧縮とアーカイブの基本',
   '複数のファイルやフォルダを「1つのファイルにまとめる」作業と、「ファイルのサイズを小さくする」作業は、しばしば同時に語られるが、実際には別の作業である。この2つの作業をそれぞれ何と呼ぶか。',
   NULL::text,
   '["まとめる作業をアーカイブ、小さくする作業を圧縮と呼ぶ", "まとめる作業を圧縮、小さくする作業をアーカイブと呼ぶ", "どちらの作業も同じ意味で、区別なく圧縮と呼ぶ", "どちらの作業も同じ意味で、区別なくアーカイブと呼ぶ"]',
   0, '[0]', 'single',
   '{"asked": "「まとめる」作業と「小さくする」作業、それぞれの正しい呼び名を問う問題。", "point": "「まとめる」はアーカイブ、「小さくする」は圧縮。別の作業。", "kid": "たくさんのファイルをバラバラのまま持ち運ぶのは面倒なので、まず1つのファイルにまとめる作業をする。これがアーカイブ。まとめただけではサイズは特に減らないので、次にそのファイルを小さくする作業をする。これが圧縮。「まとめる」と「小さくする」は目的も手順も別の作業として区別されている。", "eg": "たとえるなら、バラバラの洗濯物を1つの旅行バッグにまとめる作業(アーカイブ)と、そのバッグを圧縮袋に入れて空気を抜き小さくする作業(圧縮)は、別の工程として行われるのと同じ。", "terms": [["アーカイブ", "複数のファイルやフォルダを1つのファイルにまとめる作業"], ["圧縮", "ファイルのサイズを小さくする作業"]], "think": "なぜ2つの作業として分けて考えるのかがカギ。「まとめる」ことと「小さくする」ことは、それぞれ別の目的を持つ独立した作業。まとめるだけなら、複数のファイルを持ち運びやすい1つの塊にすることが目的で、サイズが減るとは限らない。小さくすることが目的なら、まとめる作業とは別に圧縮という工程が必要になる。この区別を理解しておくと、`.tar.gz`のような拡張子が「まとめてから小さくした」という2段階の作業の跡だと読み解けるようになる。", "vs": "「同じ作業の言い換え」という誤解に注意。世間では「圧縮する」という言葉がまとめる作業まで含めて使われがちだが、仕組みとしては別の2つの作業が組み合わさっている。", "opt": ["正解。複数のファイルを1つにまとめる作業がアーカイブ、サイズを小さくする作業が圧縮。", "アーカイブと圧縮の役割が入れ替わっており、説明が逆になっている。", "「まとめる」ことと「小さくする」ことは別の作業であり、どちらも圧縮と呼ぶのは正しくない。", "「まとめる」ことと「小さくする」ことは別の作業であり、どちらもアーカイブと呼ぶのは正しくない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">アーカイブと圧縮の2段階</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">複数ファイル</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">バラバラ</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アーカイブ</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1つにまとめる</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">圧縮</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">小さくする</text></svg>"}'),

  ('linux-q114', '圧縮とアーカイブの基本',
   '`backup.tar.gz`というファイル名を見ると、拡張子の並びだけで、そのファイルにどんな作業が行われた跡かを読み取ることができる。この拡張子が表している内容として最も適切なものはどれか。',
   NULL::text,
   '["`.tar`でまとめられたあと、`.gz`で圧縮された跡", "`.gz`でまとめられたあと、`.tar`で圧縮された跡", "`.tar`と`.gz`はどちらも同じ圧縮方式を二重にかけた跡", "拡張子の並びには特に意味はなく、単なる飾りである"]',
   0, '[0]', 'single',
   '{"asked": "`.tar.gz`という拡張子の並びが表す作業の跡を問う問題。", "point": "拡張子が並んでいる順は、行われた作業の順番をそのまま表している。", "kid": "`.tar.gz`は左から順に読むと、まず`.tar`でファイルがひとまとめにされ(アーカイブ)、そのあとに`.gz`という方式で圧縮された、という2段階の作業の跡を表している。拡張子が2つ並んでいるのは飾りではなく、行われた作業の記録そのもの。", "eg": "たとえるなら、荷物を段ボール箱にまとめてから(.tar)、その箱をビニールで真空パックした(.gz)ような状態。箱に貼られたラベルを見れば、梱包の手順がそのまま読み取れる。", "terms": [[".tar", "複数のファイルを1つにまとめた(アーカイブした)跡を表す拡張子"], [".gz", "gzipという方式で圧縮した跡を表す拡張子"]], "think": "なぜ拡張子の並び順が意味を持つのかがカギ。圧縮とアーカイブの基本カテゴリの他の問題で学んだ通り、「まとめる」と「小さくする」は別の作業。ファイルは通常、先にまとめられてから圧縮されるので、拡張子も左(先に行われた作業)から右(あとに行われた作業)の順に並ぶ。この読み方さえ分かれば、見慣れない拡張子の組み合わせに出会っても、どんな手順で作られたファイルかを推測できるようになる。", "vs": "「同じ圧縮を二重にかけた」という誤解に注意。`.tar`はまとめる作業、`.gz`は圧縮する作業であり、同じ種類の作業を2回繰り返しているわけではない。", "opt": ["正解。`.tar`でまとめられたあと、`.gz`で圧縮された跡を表している。", "作業の順番が逆になっており、実際には`.tar`でまとめてから`.gz`で圧縮するという順番になる。", "`.tar`と`.gz`はそれぞれ別の作業(まとめると小さくする)を表しており、同じ圧縮方式を二重にかけたものではない。", "拡張子の並びは行われた作業の順番を示す実質的な情報であり、単なる飾りではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">backup.tar.gz の読み方</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">元ファイル群</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">バラバラ</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">.tar</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">まとめた跡</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">.gz</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">圧縮した跡</text></svg>"}'),

  ('linux-q115', '圧縮とアーカイブの基本',
   '圧縮の仕組みを大まかに理解したい。テキストファイルの中に同じ単語や同じパターンが何度も繰り返し出てくるとき、圧縮が効きやすい理由として最も適切なものはどれか。',
   NULL::text,
   '["繰り返し出てくるパターンを、もっと短い印に置き換えて記録できるから", "繰り返しがあると、ファイルの内容が自動的に正しく直されるから", "繰り返しがあると、ファイルの保存場所が自動的に複数に分散されるから", "繰り返しがあっても圧縮の効きやすさには特に関係がない"]',
   0, '[0]', 'single',
   '{"asked": "繰り返しの多いデータで圧縮が効きやすい理由を問う問題。", "point": "圧縮の基本発想は「よく出てくるものを、短い印に置き換える」こと。", "kid": "圧縮の仕組みの多くは、「同じパターンが何度も出てくるなら、そのパターンを短い印(記号や番号)に置き換えて、あとで元に戻せるように記録しておく」という考え方をベースにしている。繰り返しが多いデータほど、この「短い印への置き換え」が何度も効くので、全体のサイズを大きく減らせる。", "eg": "たとえるなら、長い口癖を毎回全部書く代わりに「いつもの合言葉はA」と決めておいて、以降は「A」とだけ書くようなもの。同じ言葉を何度も使う文章ほど、この省略が効いて文章全体が短くなる。", "terms": [["圧縮", "データの中の規則性(繰り返しパターンなど)を利用して、記録に必要な情報量を減らす作業"]], "think": "なぜ繰り返しが多いと圧縮が効きやすいのかがカギ。圧縮は「同じ情報を何度も丸ごと書かず、1回だけ書いて、あとは短い印で済ませる」という考え方に基づいている。繰り返しの少ない、毎回違う内容のデータでは、置き換えられるパターンがほとんど無く、圧縮してもあまり小さくならない。逆にテキストのように同じ単語や構造が繰り返し出てくるデータは、この置き換えが何度も効いて、大きく圧縮できる。", "vs": "「ファイルの中身が書き直される」という誤解に注意。圧縮は記録の仕方を変えているだけで、元の内容そのものが書き換わったり修正されたりするわけではない。", "opt": ["正解。繰り返し出てくるパターンを、もっと短い印に置き換えて記録できることが圧縮の効きやすさにつながる。", "圧縮は記録の仕方を変える作業であり、ファイルの内容を自動的に修正する仕組みではない。", "圧縮は保存場所を分散させる仕組みではなく、1つのファイルの中の記録の仕方を工夫する作業。", "繰り返しの多さは圧縮の効きやすさに直結しており、無関係ではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">繰り返しが少ない vs 多い</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">繰り返し少ない</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">置き換えがほぼ効かない</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">圧縮しにくい</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">繰り返し多い</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">短い印に置き換え</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">圧縮しやすい</text></svg>"}'),

  ('linux-q116', '圧縮とアーカイブの基本',
   'すでに`.jpg`や`.mp4`のような形式で保存されている画像・動画ファイルを、さらにgzipのような汎用の圧縮ツールにかけても、サイズがほとんど減らないことが多い。この理由として最も適切なものはどれか。',
   NULL::text,
   '["画像や動画の形式自体が、保存する時点ですでに圧縮された状態になっているから", "画像や動画のファイルは、法律でこれ以上圧縮してはいけないと決まっているから", "画像や動画のファイルには、繰り返しパターンが常に大量に含まれているから", "汎用の圧縮ツールは、画像や動画のファイルだけ処理を拒否する仕組みだから"]',
   0, '[0]', 'single',
   '{"asked": "画像・動画をさらに圧縮してもサイズが減りにくい理由を問う問題。", "point": "すでに圧縮済みのデータには、圧縮ツールの「置き換えの種」がほとんど残っていない。", "kid": "`.jpg`や`.mp4`のような形式は、保存する時点ですでに専用の方法で圧縮された状態になっている。圧縮とは「繰り返しパターンを短い印に置き換える」作業だが、すでに圧縮済みのデータは、そのパターンをあらかた使い切ってしまっているため、あとから別の圧縮ツールをかけても、置き換えられる余地がほとんど残っていない。", "eg": "たとえるなら、すでに真空パックされた食品を、もう一度別の真空パック機にかけても、これ以上空気を抜きようがないのと同じ。最初のパックの時点で、抜ける空気はもう抜き切っている。", "terms": [["すでに圧縮済みのデータ", "保存の時点で、専用の方式によりすでに圧縮されているデータの形式"]], "think": "なぜ二重に圧縮しても効果が薄いのかがカギ。圧縮とアーカイブの基本カテゴリの別の問題で学んだ通り、圧縮の基本原理は「繰り返しパターンを短い印に置き換える」こと。画像や動画の専用形式は、保存する段階でこの置き換えをすでに行い切っているため、データの並びが一見ランダムに近い状態になっている。そこに汎用の圧縮ツールをかけても、置き換えられるパターンがほとんど見つからず、サイズはあまり変わらない。", "vs": "「常に大量の繰り返しがある」という誤解に注意。むしろ逆で、すでに圧縮済みのデータは繰り返しパターンが使い切られており、新たな圧縮ツールから見ると繰り返しの少ないデータに見える。", "opt": ["正解。画像や動画の形式自体が、保存する時点ですでに圧縮された状態になっているため、さらに圧縮しても効果が薄い。", "圧縮の可否を定めた法律のような決まりは存在せず、圧縮できるかどうかは技術的な理由による。", "すでに圧縮済みのデータは繰り返しパターンが使い切られており、大量の繰り返しが残っているという記述は逆。", "汎用の圧縮ツール自体は画像や動画ファイルの処理を拒否するわけではなく、処理はできるがサイズがあまり減らないだけ。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">未圧縮データ vs 圧縮済みデータ</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">未圧縮データ</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">繰り返しが残る</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">圧縮でよく縮む</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">圧縮済み(.jpg等)</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">繰り返しを使い切り済み</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">さらに縮みにくい</text></svg>"}'),

  ('linux-q117', '圧縮とアーカイブの基本',
   'テストの実行証跡(ログ・スクリーンショットなど大量のファイル)を長期保管したい。これらをアーカイブしてから圧縮しておくと便利な理由として最も適切なものはどれか。',
   NULL::text,
   '["1つのファイルにまとまり、保管・受け渡しがしやすくなり、サイズも小さくなるから", "アーカイブして圧縮すると、ファイルの中身の検索が自動的に速くなるから", "アーカイブして圧縮すると、テストの実行結果が自動的に正しく修正されるから", "アーカイブして圧縮しないと、そもそもファイルを保存すること自体ができないから"]',
   0, '[0]', 'single',
   '{"asked": "テスト証跡をアーカイブ・圧縮して保管する利点を問う問題。", "point": "「まとめて」「小さくして」保管・受け渡ししやすくするのが実務上の利点。", "kid": "テストの実行証跡は、ログやスクリーンショットなど大量の細かいファイルになりがち。これらをバラバラのまま保管したり誰かに送ったりするのは大変。アーカイブで1つのファイルにまとめ、さらに圧縮してサイズを小さくしておけば、保管も受け渡しもぐっと楽になる。", "eg": "たとえるなら、大量の書類をバラバラのまま棚にしまうより、1つのファイルボックスにまとめて(アーカイブ)、さらに圧縮袋で小さくして(圧縮)保管するほうが、場所も取らず持ち運びもしやすいのと同じ。", "terms": [["実行証跡", "テストを実行した記録として残すログやスクリーンショットなどのファイル"], ["長期保管", "あとから見返せるように、しばらくの間保存しておくこと"]], "think": "なぜテスト証跡の保管に向いているのかがカギ。QA実務では、大量の細かいファイルをそのまま長期間保管すると、ファイル数が多すぎて管理しづらく、ディスクの容量も圧迫しやすい。アーカイブでひとまとめにすれば「1つの塊」として扱いやすくなり、さらに圧縮すればディスク使用量も抑えられる。この2つの作業を組み合わせることで、保管のしやすさとサイズの節約を同時に達成できる。", "vs": "「検索が自動的に速くなる」という誤解に注意。アーカイブ・圧縮はファイルをまとめて小さくする作業であり、中身の検索性能を直接改善する仕組みではない。", "opt": ["正解。1つのファイルにまとまり、保管・受け渡しがしやすくなり、サイズも小さくなることが主な利点。", "アーカイブ・圧縮はファイルの保存形式を変える作業であり、検索の速さを自動的に改善する仕組みではない。", "アーカイブ・圧縮はファイルの記録の仕方を変えるだけで、テストの実行結果の中身を修正する仕組みではない。", "アーカイブ・圧縮をしなくてもファイル自体は保存できるので、保存すること自体ができないという記述は誤り。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">テスト証跡の保管</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">大量の証跡</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ログ/画像</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アーカイブ+圧縮</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1つに・小さく</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">長期保管</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">受け渡しも楽</text></svg>"}'),

  ('linux-q118', '圧縮とアーカイブの基本',
   'アーカイブしたファイルを元のバラバラのファイル群に戻す作業を何と呼ぶか、圧縮したファイルを元のサイズに戻す作業を何と呼ぶか、正しい組み合わせはどれか。',
   NULL::text,
   '["アーカイブを戻す作業を展開(または解凍)、圧縮を戻す作業も展開(または解凍)と呼ぶことが多い", "アーカイブを戻す作業を圧縮、圧縮を戻す作業をアーカイブと呼ぶ", "アーカイブと圧縮を戻す作業には、それぞれ元に戻せない専用の名前しかない", "一度アーカイブ・圧縮したファイルは、二度と元の状態には戻せない"]',
   0, '[0]', 'single',
   '{"asked": "アーカイブ・圧縮を元に戻す作業の呼び名を問う問題。", "point": "まとめる/小さくするの逆方向は、どちらも「展開(解凍)」とまとめて呼ばれることが多い。", "kid": "アーカイブや圧縮でひとまとめ・小さくしたファイルは、元に戻すこともできる。この「元に戻す」作業は、アーカイブを戻す場合も圧縮を戻す場合も、まとめて「展開」や「解凍」と呼ばれることが多い。作業の方向(まとめる/小さくする、それを戻す)が変わるだけで、逆再生のようなイメージ。", "eg": "たとえるなら、圧縮袋で小さくした布団を、袋から出してふくらませる作業も「展開」と呼べるし、段ボール箱にまとめた荷物を、箱から出して元通りバラバラに広げる作業も「展開」と呼べる。どちらも「まとめた・縮めた状態を元に戻す」という同じ方向の作業。", "terms": [["展開(解凍)", "アーカイブ・圧縮したファイルを、元の状態に戻す作業"]], "think": "なぜ同じ呼び名でまとめられるのかがカギ。アーカイブと圧縮は別の作業だが、どちらも「元の状態から、扱いやすい状態に変換する」という方向は共通している。それを元に戻す作業も、方向としては同じ「変換したものを元に戻す」という共通点があるため、細かい違い(まとめたのか小さくしたのか)にかかわらず、展開や解凍という同じ言葉でまとめて呼ばれることが多い。", "vs": "「アーカイブと圧縮を戻す作業に別々の対になる名前がある」という誤解に注意。それぞれ専用の道具(コマンド)は別だが、日常的な呼び名としては両方とも「展開」「解凍」という同じ言葉が使われることが多い。", "opt": ["正解。アーカイブを戻す作業も圧縮を戻す作業も、どちらも展開(または解凍)と呼ばれることが多い。", "アーカイブと圧縮を戻す作業の呼び名が入れ替わっており、まとめる/小さくする作業自体の呼び名と混同している。", "元に戻す作業には展開・解凍という共通の呼び名が使われることが多く、専用の名前しかないという記述は誤り。", "アーカイブ・圧縮は情報を保ったまま形式を変える作業なので、正しい手順を踏めば元の状態に戻すことができる。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">元に戻す(展開/解凍)</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">圧縮+アーカイブ済み</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">小さい1ファイル</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">展開/解凍</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">逆再生</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">元のファイル群</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">バラバラに復元</text></svg>"}'),

  ('linux-q119', 'ディストリビューションの違い',
   '「Linuxは1つのOSではなく、いくつもの種類(ディストリビューション)がある」とよく言われる。この状況を最も正確に説明しているものはどれか。',
   NULL::text,
   '["カーネルという核の部分は共通し、その周りに組み合わせる道具や設定が違う種類が複数存在する", "ディストリビューションごとに、まったく別のカーネルが独自に開発されている", "ディストリビューションという言葉は俗称にすぎず、実際にはLinuxは1種類しか存在しない", "ディストリビューションの違いは見た目の色使いだけで、内部の仕組みはすべて同一である"]',
   0, '[0]', 'single',
   '{"asked": "「Linuxは1つではない」という状況の正確な説明を問う問題。", "point": "共通しているのはカーネル、違うのは周りに組み合わせる道具や設定。", "kid": "「Linuxにはいろんな種類がある」と聞くと、まったく別々のOSが乱立しているように聞こえるかもしれない。しかし実際には、コンピュータとOSの中身のカテゴリで学んだ「カーネル」という核の部分は共通していることが多く、その周りに組み合わせるパッケージ管理の仕組みや初期設定、デスクトップ環境などが違う「セット」が、それぞれ別のディストリビューションとして配られている。", "eg": "たとえるなら、同じ「カレーのルー(カーネル)」を使っていても、それに合わせる具材や盛り付け方(周りの道具・設定)が違うお店がいくつもあるようなもの。ベースは共通していても、お店ごとに個性が出る。", "terms": [["ディストリビューション", "共通のカーネルに、パッケージ管理などの道具や設定を組み合わせて配布されるLinuxのセット"], ["カーネル", "ハードウェアとの橋渡しを行う、OSの核となる部分"]], "think": "なぜ「別々のOS」ではなく「同じ核を使う複数のセット」と理解すべきかがカギ。もし本当にディストリビューションごとにまったく別のカーネルが動いていたら、共通の知識(プロセスやファイルシステムの仕組みなど)がディストリビューションをまたいで通用しないことになってしまう。実際には核の部分が共通しているからこそ、この問題集で学んできたプロセス・ファイルシステム・権限といった本質的な仕組みは、どのディストリビューションでも同じように成り立つ。", "vs": "「まったく別のOSの寄せ集め」という誤解に注意。核となるカーネルは共通しており、違うのはその周りに組み合わせる道具や設定であって、内部の本質的な仕組みまで別物というわけではない。", "opt": ["正解。カーネルという核の部分は共通し、その周りに組み合わせる道具や設定が違う種類が複数存在する。", "多くのディストリビューションは共通のカーネルをベースにしており、まったく別のカーネルを独自開発しているわけではない。", "ディストリビューションは実際に複数の系統・種類として広く使われており、俗称で1種類しか無いという記述は誤り。", "ディストリビューションの違いは見た目だけでなく、パッケージ管理の作法など内部の仕組みにも違いがある。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">共通のカーネルから枝分かれ</text><rect x=\"140\" y=\"32\" width=\"60\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"170\" y=\"49\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">カーネル(共通)</text><line x1=\"170\" y1=\"58\" x2=\"55.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"10.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"55.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ディストリA</text><line x1=\"170\" y1=\"58\" x2=\"170.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"125.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ディストリB</text><line x1=\"170\" y1=\"58\" x2=\"285.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"240.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"285.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ディストリC</text></svg>"}'),

  ('linux-q120', 'ディストリビューションの違い',
   'ディストリビューションとは、具体的にどのようなものをひとまとめにして配布したものと考えるのが最も適切か。',
   NULL::text,
   '["カーネルに加え、パッケージ管理の仕組みや初期設定などを組み合わせて配布用にまとめたもの", "ハードウェアの部品そのものを、メーカーごとにまとめて配布したもの", "特定のプログラミング言語だけを集めて配布したもの", "インターネット回線の契約プランをまとめて配布したもの"]',
   0, '[0]', 'single',
   '{"asked": "ディストリビューションが何をまとめたものかを問う問題。", "point": "ディストリビューションの中身は「カーネル＋周りの道具・設定一式」。", "kid": "ディストリビューションは、カーネルという核だけでなく、パッケージ管理の考え方のカテゴリで学んだパッケージマネージャや、初期設定、よく使う基本的なプログラム一式などを、あらかじめ組み合わせて「すぐ使える状態」にまとめて配布したもの。利用者は、これらを1つずつ個別に集めて組み立てる手間を省ける。", "eg": "たとえるなら、パーツを1つずつ買い集めて自作するパソコンではなく、必要な部品があらかじめ組み込まれた完成品のパソコンを買うようなもの。ディストリビューションは、Linuxを使うために必要な部品一式があらかじめ組み合わされた「完成品セット」に近い。", "terms": [["ディストリビューション", "カーネルとパッケージ管理の仕組みなどを組み合わせて配布用にまとめたセット"], ["パッケージ管理の仕組み", "パッケージ管理の考え方のカテゴリで学んだ、依存関係を解決しながらソフトをインストールする仕組み"]], "think": "なぜ「まとめて配布する」ことに意味があるのかがカギ。カーネルだけを渡されても、それを動かすための基本的な道具(パッケージ管理の仕組みや初期設定)が無ければ、実際に使える状態にするまでに大変な手間がかかる。ディストリビューションは、この「すぐ使える状態にするための一式」をあらかじめ組み合わせておくことで、利用者がゼロから全部を組み立てる必要をなくしている。", "vs": "「ハードウェアの部品をまとめたもの」という誤解に注意。ディストリビューションはソフトウェア(カーネルと周りの道具)の組み合わせであり、物理的なハードウェアの部品をまとめたものではない。", "opt": ["正解。カーネルに加え、パッケージ管理の仕組みや初期設定などを組み合わせて配布用にまとめたものがディストリビューション。", "ディストリビューションはソフトウェアの組み合わせであり、物理的なハードウェアの部品をまとめたものではない。", "ディストリビューションは特定のプログラミング言語だけを集めたものではなく、OSとして動くために必要な一式を指す。", "ディストリビューションはソフトウェアのセットであり、通信回線の契約プランとは無関係。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ディストリビューションの中身</text><rect x=\"40\" y=\"30\" width=\"260\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"170\" y=\"47.0\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">初期設定・基本アプリ</text><rect x=\"40\" y=\"62\" width=\"260\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"79.0\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">パッケージ管理の仕組み</text><rect x=\"40\" y=\"94\" width=\"260\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"111.0\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">カーネル</text></svg>"}'),

  ('linux-q121', 'ディストリビューションの違い',
   'パッケージ管理の考え方のカテゴリで学んだ「依存関係を解決しながらインストールする」という考え方自体は、Debian系とRedHat系のディストリビューションで共通している。では何が違うのか、最も適切な説明はどれか。',
   NULL::text,
   '["それぞれ別の歴史の中で独自に発展してきたため、使う道具やパッケージの形式が違う", "Debian系にはパッケージ管理の仕組みが存在せず、RedHat系にだけ存在する", "RedHat系にはパッケージ管理の仕組みが存在せず、Debian系にだけ存在する", "両者は名前が違うだけで、使うコマンドも設定ファイルの形式もまったく同一である"]',
   0, '[0]', 'single',
   '{"asked": "Debian系とRedHat系でパッケージ管理の何が違うのかを問う問題。", "point": "違うのは「考え方」ではなく「別々に発展してきた道具・形式」。", "kid": "Debian系もRedHat系も、パッケージ管理の考え方のカテゴリで学んだ「依存関係を解決しながらソフトを入れる」という発想自体は同じ。ただ、それぞれ別々の歴史の中で独自に道具を作り育ててきたため、実際に使うコマンドの名前や、パッケージファイルの形式(拡張子など)が違う、というだけの違いになる。", "eg": "たとえるなら、日本語と英語のように、どちらも「意思を伝える」という同じ目的を持つ言語でありながら、別々の歴史の中で発展したため、単語や文法(コマンドや形式)が違うのと同じ。伝えたいこと(依存関係の解決)自体は共通している。", "terms": [["Debian系", "Debianというディストリビューションを起源に持つ系統。独自のパッケージ形式・道具を使う"], ["RedHat系", "RedHatというディストリビューションを起源に持つ系統。Debian系とは別のパッケージ形式・道具を使う"]], "think": "なぜ「考え方は同じ、道具が違う」と理解すべきかがカギ。もし考え方自体が根本から違っていたら、片方の知識がもう片方にまったく応用できないことになってしまう。しかし実際には「依存関係を解決しながらインストールする」という本質は共通しているので、片方の系統でこの考え方を理解しておけば、もう片方の系統に出会っても、道具の名前が違うだけで戸惑わずに済む。", "vs": "「どちらかにはパッケージ管理の仕組みが存在しない」という誤解に注意。どちらの系統にもパッケージ管理の仕組みは存在し、違うのはその実装(道具や形式)であって、有無の違いではない。", "opt": ["正解。それぞれ別の歴史の中で独自に発展してきたため、使う道具やパッケージの形式が違う。", "Debian系にもパッケージ管理の仕組みは存在しており、存在しないという記述は誤り。", "RedHat系にもパッケージ管理の仕組みは存在しており、存在しないという記述は誤り。", "使うコマンドやパッケージ形式は系統ごとに異なっており、まったく同一というのは誤り。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Debian系 vs RedHat系</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">Debian系</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">独自の道具・形式</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">同じ考え方</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">RedHat系</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">別の道具・形式</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">同じ考え方</text></svg>"}'),

  ('linux-q122', 'ディストリビューションの違い',
   'サーバー用途に向けて安定性を重視したディストリビューションもあれば、デスクトップでの使いやすさを重視したディストリビューションもある。複数のディストリビューションが存在する理由として最も適切なものはどれか。',
   NULL::text,
   '["用途や思想によって、重視したい点(安定性・使いやすさなど)が異なるため", "複数存在しているのは単なる偶然で、特に理由なく増え続けているだけ", "1つのディストリビューションだけでは、技術的にOSとして動作させることができないため", "複数存在する目的は、利用者を混乱させることだけにある"]',
   0, '[0]', 'single',
   '{"asked": "複数のディストリビューションが存在する理由を問う問題。", "point": "複数存在するのは「重視したい点」がディストリビューションごとに違うから。", "kid": "ディストリビューションを作る側にも、それぞれ「何を大事にしたいか」という思想がある。サーバー用途では、めったに設定が変わらず長期間安定して動き続けることが重視されやすい。デスクトップ用途では、見た目の使いやすさや最新のソフトがすぐ使えることが重視されやすい。この「何を重視するか」の違いが、複数のディストリビューションが存在する理由になっている。", "eg": "たとえるなら、同じ「移動する」という目的でも、荷物をたくさん運ぶことを重視した車と、燃費の良さを重視した車があるように、目的や重視する点が違えば、それに合わせた別々の選択肢が生まれるのと同じ。", "terms": [["用途", "そのディストリビューションが主にどんな場面で使われることを想定しているか"], ["思想", "何を重視して設計されているかという、開発の方向性"]], "think": "なぜ「1つに統一されない」のかがカギ。もし全員にとって理想の設定が1つに定まるなら、ディストリビューションは1種類で足りるはずだが、実際には「安定性を最優先したい人」と「常に最新の機能を使いたい人」のように、利用者ごとに重視したい点が異なる。この多様な需要に応えるために、それぞれ違う思想を持った複数のディストリビューションが存在し続けている。", "vs": "「単なる偶然・混乱させるため」という誤解に注意。複数のディストリビューションが存在するのは、利用者の用途や重視する点の違いという実質的な理由に基づいており、無目的に増えているわけではない。", "opt": ["正解。用途や思想によって、重視したい点(安定性・使いやすさなど)が異なるため、複数のディストリビューションが存在する。", "複数存在するのは用途や思想の違いという実質的な理由に基づいており、単なる偶然ではない。", "1つのディストリビューションでもOSとして動作させること自体は可能で、技術的に不可能というわけではない。", "複数のディストリビューションが存在する目的は利用者の多様な需要に応えることであり、混乱させることではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">重視する点の違い</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">サーバー向け</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">安定性を重視</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">変化が少ない</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">デスクトップ向け</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">使いやすさを重視</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">最新機能を重視</text></svg>"}'),

  ('linux-q123', 'ディストリビューションの違い',
   'コンテナの正体のカテゴリで学んだ通り、コンテナはホストとカーネルを共有している。それでも、コンテナのベースイメージとして「Ubuntu」や「Alpine」のような特定のディストリビューション名が選ばれるのはなぜか。',
   NULL::text,
   '["カーネルは共有していても、パッケージ管理の仕組みや周りの道具はディストリビューションごとに異なるため", "コンテナごとに、カーネルそのものを個別にインストールし直す必要があるため", "ディストリビューション名は見た目のラベルにすぎず、中身の動作にはまったく影響しないため", "ベースイメージの選択は、コンテナの起動速度とは無関係な、単なる好みの問題でしかないため"]',
   0, '[0]', 'single',
   '{"asked": "コンテナのベースイメージにディストリビューション名が選ばれる理由を問う問題。", "point": "カーネルは共有でも、パッケージ管理などの「周りの道具」はイメージごとに選べる。", "kid": "コンテナの正体のカテゴリで学んだ通り、コンテナはホストのカーネルをそのまま間借りして使っている。しかしコンテナの中で使うパッケージ管理の仕組みや、あらかじめ入っている基本的な道具は、ベースイメージとして選んだディストリビューションによって変わる。だから「Ubuntuベース」「Alpineベース」のように、ディストリビューション名がイメージの個性を表す目印として使われる。", "eg": "たとえるなら、同じ校舎(カーネル)を間借りして開かれる複数の教室(コンテナ)でも、教室ごとに置いてある教材や文房具の種類(パッケージ管理の仕組みや道具)が違う、というイメージ。校舎は共有していても、教室の中身は選べる。", "terms": [["ベースイメージ", "コンテナを作る元になる、あらかじめ用意された土台の環境"], ["Alpine", "非常に軽量なことで知られるディストリビューションの1つ。コンテナのベースイメージとしてよく使われる"]], "think": "なぜカーネルを共有していても違いが出るのかがカギ。コンテナの正体のカテゴリで学んだ通り、コンテナが隔離しているのは「見える範囲(namespace)」や「使える量(cgroup)」であって、カーネルそのものは共有される。しかしパッケージ管理の仕組みや、あらかじめ入っている道具一式は、カーネルとは別の「周りの部分」に属する。この部分はベースイメージとして選んだディストリビューションごとに異なるため、選ぶイメージによってコンテナの中の使い勝手やサイズが変わってくる。", "vs": "「カーネルごと個別にインストールされる」という誤解に注意。コンテナの正体のカテゴリで学んだ通り、カーネルはホストと共有されており、コンテナごとに個別のカーネルを持つわけではない。", "opt": ["正解。カーネルは共有していても、パッケージ管理の仕組みや周りの道具はディストリビューションごとに異なるため、ベースイメージの選択に意味がある。", "コンテナはホストのカーネルを共有しており、コンテナごとにカーネルを個別にインストールし直す仕組みではない。", "ディストリビューション名はパッケージ管理の仕組みなど実際の中身の違いを表しており、単なる見た目のラベルではない。", "ベースイメージによってあらかじめ入っている道具の量が変わるため、サイズや起動の軽さに関わる実質的な選択になる。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コンテナのベースイメージ</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"38\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">共有される部分</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">ホストのカーネル</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">選べる部分</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">パッケージ管理の仕組み</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">基本的な道具一式</text></svg>"}'),

  ('linux-q124', 'ディストリビューションの違い',
   'ディストリビューションごとにパッケージ管理の作法や見た目は違っても、この問題集でここまで学んできたプロセス・ファイルシステム・権限といった仕組みについて、最も適切な理解はどれか。',
   NULL::text,
   '["ディストリビューションが違っても、共通のカーネルに支えられた本質的な仕組みとして変わらない", "ディストリビューションごとに、プロセスやファイルシステムの根本的な仕組みがまったく別物になる", "権限の仕組みだけは、ディストリビューションによって完全に異なる考え方が採用されている", "ファイルシステムの木構造という考え方は、一部のディストリビューションにしか存在しない"]',
   0, '[0]', 'single',
   '{"asked": "ディストリビューションが違っても変わらない本質的な仕組みを問う問題。", "point": "パッケージ管理などの「周り」は違っても、カーネルに支えられた本質は共通。", "kid": "この問題集でここまで学んできたプロセス・ファイルシステム・権限といった仕組みは、ディストリビューションの違いを説明した最初の問題で学んだ通り、共通のカーネルに支えられている。だから、パッケージ管理の作法や見た目が違うディストリビューションであっても、これらの本質的な仕組みは変わらず同じように成り立つ。", "eg": "たとえるなら、方言(パッケージ管理の作法や見た目)が違う地域どうしでも、日本語という言語としての基本的な文法(プロセス・ファイルシステム・権限の仕組み)は共通しているのと同じ。方言を1つ覚えれば、他の地域の言葉にも応用が利く。", "terms": [["本質的な仕組み", "ディストリビューションの違いを超えて共通する、カーネルに支えられた基本の考え方"]], "think": "なぜ本質的な仕組みは変わらないと言えるのかがカギ。ディストリビューションの違いを説明した最初の問題で学んだ通り、違いが生まれるのはカーネルの周りに組み合わせる道具や設定の部分であり、カーネル自体は共通していることが多い。プロセス・ファイルシステム・権限といった仕組みは、まさにこのカーネルが担っている本質的な機能なので、ディストリビューションが違っても同じように理解して使い回せる。だからこそ、この問題集で学んできた内容は、特定のディストリビューションに縛られない知識になる。", "vs": "「ディストリビューションごとに根本から別物になる」という誤解に注意。違うのはパッケージ管理の作法や見た目などの「周りの部分」であり、カーネルに支えられた根本的な仕組みまで別物になるわけではない。", "opt": ["正解。ディストリビューションが違っても、共通のカーネルに支えられた本質的な仕組みとして変わらない。", "プロセスやファイルシステムの根本的な仕組みは共通のカーネルに支えられており、まったく別物になるわけではない。", "権限の仕組みも共通のカーネルに支えられた本質的な部分であり、ディストリビューションごとに完全に異なるわけではない。", "ファイルシステムの木構造という考え方は特定のディストリビューションに限られたものではなく、共通の本質的な仕組み。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">違っても変わらない本質</text><rect x=\"40\" y=\"30\" width=\"260\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"170\" y=\"47.0\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">パッケージ管理(違う)</text><rect x=\"40\" y=\"62\" width=\"260\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"79.0\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセス/ファイルシステム/権限(共通)</text><rect x=\"40\" y=\"94\" width=\"260\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"111.0\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">カーネル(共通)</text></svg>"}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'linux-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;